//! Vectors for the instantiable cores of `blocks/iop/` (mask ledgers, statement/layout, BAT,
//! laid, single rows, BATT), generated by `scripts/cpp_vectors/iop_core_vectors.cpp`.

use std::collections::HashMap;

use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::iop::bat::combine;
use fp_core::iop::batt::{batt_claim, batt_k_col, batt_row, TensorRow};
use fp_core::iop::context::{Column, Opened};
use fp_core::iop::laid::{laid_block_ok, laid_form, laid_ok, laid_tensor, IndexWeights, LaidBlock, LaidMatrix};
use fp_core::iop::mask::{receipt_for_a_test, MaskLedger, MaskTerm, SendAccess};
use fp_core::iop::hp::Weight;
use fp_core::iop::psc::{psc_masks, psc_rows, psc_vars, KeptTerm, PscOutput};
use fp_core::iop::summand::{SumClaim, Summand};
use fp_core::iop::relation::{Codes, OracleShape, Part, Row, Statement};
use fp_core::iop::single_rows::{single_rows_symbols, SingleRows};
use fp_core::iop::tensor::Tensor;

const VECTORS: &str = include_str!("../../fixtures/iop_core_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}
fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([
        F(u64::from_str_radix(p[0], 16).unwrap()),
        F(u64::from_str_radix(p[1], 16).unwrap()),
        F(u64::from_str_radix(p[2], 16).unwrap()),
    ])
}
fn mk(x: u64) -> E {
    E([F(x), F(x + 1), F(x + 2)])
}
fn elist(s: &str) -> Vec<E> {
    if s == "-" {
        return Vec::new();
    }
    s.split(';').map(e).collect()
}
fn hex(v: &[E]) -> String {
    v.iter()
        .map(|x| format!("{:016x},{:016x},{:016x}", x.0[0].0, x.0[1].0, x.0[2].0))
        .collect::<Vec<_>>()
        .join(";")
}
fn idlist(name: &str, v: &[u64]) -> String {
    if v.is_empty() {
        return "-".to_string();
    }
    let _ = name;
    v.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(";")
}

#[test]
fn iop_core_vectors_match_the_cpp_reference() {
    let mut seen_ledger = false;
    let mut seen_layout = false;
    let mut seen_bat = false;
    let mut seen_laid = false;
    let mut seen_symbols = false;
    let mut seen_batt = false;

    for line in VECTORS.lines() {
        let first = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        match first {
            "LEDGER" => {
                assert_eq!(kv["oracle"].parse::<u32>().unwrap(), 4);
                let mut l = MaskLedger::new(receipt_for_a_test(4, 0, 7, 3, 2));
                let mut got = Vec::new();
                while l.left() > 0 {
                    got.push(l.take().index() as u64);
                }
                assert_eq!(idlist("taken", &got), kv["taken"]);
                assert_eq!(l.left().to_string(), kv["left"]);
                seen_ledger = true;
            }
            "LEDGER_CLOSED" => {
                let mut l = MaskLedger::new(receipt_for_a_test(4, 0, 7, 3, 2));
                l.close();
                assert_eq!(l.left().to_string(), kv["left"]);
            }
            "LAYOUT" => {
                let (mut s, _, g, _) = statement();
                let l = s.layout(g);
                assert_eq!(l.k.to_string(), kv["k"]);
                assert_eq!(l.h.to_string(), kv["h"]);
                assert_eq!(l.log_ell.to_string(), kv["log_ell"]);
                assert_eq!(l.log_ell_zk.to_string(), kv["log_ell_zk"]);
                assert_eq!(idlist("members", &l.members.iter().map(|x| *x as u64).collect::<Vec<_>>()), kv["members"]);
                let kept = l.kept.iter().map(|x| if *x { "1" } else { "0" }).collect::<Vec<_>>().join(";");
                assert_eq!(kept, kv["kept"]);
                assert_eq!(idlist("main_first", &l.main_first), kv["main_first"]);
                assert_eq!(idlist("mask_first", &l.mask_first), kv["mask_first"]);
                seen_layout = true;
            }
            "BAT" => {
                assert_eq!(kv["k"], "1");
                assert_eq!(kv["h"], "1");
                seen_bat = true;
            }
            "BAT_FORM" => {
                let (mut s, x, g, _) = statement();
                let input = s.begin_run(g);
                let out = combine(&s, g, input, x);
                assert_eq!(&kv["target"], &format!("{:016x},{:016x},{:016x}", out.target.0[0].0, out.target.0[1].0, out.target.0[2].0));
                let vars: u32 = kv["vars"].parse().unwrap();
                let mut c = Vec::new();
                for j in 0..(1u64 << vars) {
                    c.push(out.c.at(j));
                }
                assert_eq!(hex(&c), kv["c"], "BAT_FORM c");
                seen_bat = true;
            }
            "BAT_D" => {
                let (mut s, x, g, _) = statement();
                let input = s.begin_run(g);
                let out = combine(&s, g, input, x);
                assert_eq!(hex(&out.d), kv["d"], "BAT_D d");
            }
            "LAID_BLOCK" => {
                let b = laid_block();
                assert_eq!((laid_block_ok(&b, 2, 2) as u8).to_string(), kv["ok"]);
            }
            "LAID_MATRIX" => {
                let m = LaidMatrix { size_i: 4, size_c: 4, blocks: vec![laid_block()] };
                assert_eq!((laid_ok(&[m], 2, 2) as u8).to_string(), kv["ok"]);
            }
            "LAID_TENSOR" => {
                let b = laid_block();
                let on_i = IndexWeights::eq(&[mk(1), mk(2)]);
                let on_c = IndexWeights::powers(mk(3), 2);
                let t = laid_tensor(&b, 2, 2, &on_i, &on_c, mk(5));
                assert_eq!(t.vars().to_string(), kv["vars"]);
                assert_eq!(format!("{:016x},{:016x},{:016x}", t.scalar.0[0].0, t.scalar.0[1].0, t.scalar.0[2].0), kv["scalar"]);
                let at: Vec<E> = (0..16).map(|j| t.at(j)).collect();
                assert_eq!(hex(&at), kv["at"], "laid tensor at");
                seen_laid = true;
            }
            "LAID_FORM" => {
                let b = laid_block();
                let on_i = IndexWeights::eq(&[mk(1), mk(2)]);
                let on_c = IndexWeights::powers(mk(3), 2);
                let f = laid_form(&[b], 2, 2, &on_i, &on_c, mk(5));
                let fa: Vec<E> = (0..16).map(|j| f.at(j)).collect();
                assert_eq!(hex(&fa), kv["f"], "laid form");
            }
            "SYMBOLS" => {
                let (mut s, _, g, _) = statement();
                let l = s.layout(g);
                let mut sr = SingleRows { code: 0, mask_code: 0, layout: l, gamma: vec![mk(1)], masks: 2, fresh: 1, ..SingleRows::default() };
                sr.kept_rows = 0;
                let mut opened = Opened::default();
                opened.of = vec![
                    vec![
                        Column { main: vec![mk(10), mk(20)], mask: vec![mk(30), mk(40)] },
                        Column { main: vec![mk(11), mk(21)], mask: vec![mk(31), mk(41)] },
                    ],
                    vec![
                        Column { main: Vec::new(), mask: vec![mk(70), mk(80)] },
                        Column { main: Vec::new(), mask: vec![mk(71), mk(81)] },
                    ],
                ];
                let y = single_rows_symbols(&sr, &opened, 2);
                assert_eq!(sr.rows().to_string(), kv["rows"]);
                assert_eq!(hex(&y), kv["y"], "single rows symbols");
                seen_symbols = true;
            }
            "BATT" => {
                let (rows, ledger) = batt_rows();
                let mut rows = rows;
                let mut l = ledger;
                rows[0].masks = vec![MaskTerm { slot: l.take(), coeff: mk(3) }];
                rows[1].masks = vec![MaskTerm { slot: l.take(), coeff: mk(6) }];
                let b = batt_claim(&mut rows, mk(33));
                assert_eq!(batt_k_col(&rows).to_string(), kv["k_col"]);
                assert_eq!(hex(&b.chi), kv["chi"]);
                assert_eq!(
                    format!("{:016x},{:016x},{:016x}", b.claim.target.0[0].0, b.claim.target.0[1].0, b.claim.target.0[2].0),
                    kv["target"]
                );
                assert_eq!(b.claim.masks.len().to_string(), kv["masks"]);
                assert_eq!(b.claim.vars.len().to_string(), kv["vars"]);
                assert_eq!(b.summand.shown.to_string(), kv["shown"]);
                assert_eq!(b.summand.kept.to_string(), kv["kept"]);
                assert_eq!(b.summand.degree.to_string(), kv["degree"]);
                seen_batt = true;
            }
            "BATT_AT" => {
                let (mut rows, mut l) = batt_rows();
                rows[0].masks = vec![MaskTerm { slot: l.take(), coeff: mk(3) }];
                rows[1].masks = vec![MaskTerm { slot: l.take(), coeff: mk(6) }];
                let b = batt_claim(&mut rows, mk(33));
                let a = (b.summand.at)(&[mk(40), mk(41)], &[]);
                assert_eq!(hex(&a), kv["a"], "BATT at");
            }
            "BATT_ROW" => {
                let (mut rows, mut l) = batt_rows();
                let b = batt_claim(&mut rows, mk(33));
                let _ = b;
                let out = PscOutput {
                    point: vec![mk(50), mk(51)],
                    row_masks: vec![MaskTerm { slot: l.take(), coeff: mk(10) }],
                    row_maps: vec![KeptTerm { map: 0, coeff: mk(9) }],
                    row_target: mk(52),
                    ends: Vec::new(),
                };
                let r = batt_row(&rows, out);
                assert_eq!(r.g.len().to_string(), kv["g"]);
                assert_eq!(format!("{:016x},{:016x},{:016x}", r.g[0].scalar.0[0].0, r.g[0].scalar.0[1].0, r.g[0].scalar.0[2].0), kv["scalar"]);
                assert_eq!(hex(&r.psi), kv["psi"]);
                assert_eq!(format!("{:016x},{:016x},{:016x}", r.target.0[0].0, r.target.0[1].0, r.target.0[2].0), kv["target"]);
                assert_eq!(r.masks.len().to_string(), kv["masks"]);
            }
            "PSC_POINT" => {
                let out = psc_output();
                assert_eq!(hex(&out.point), kv["PSC_POINT"]);
                assert_eq!(out.row_masks.len().to_string(), kv["masks"]);
                assert_eq!(out.row_maps.len().to_string(), kv["keeps"]);
                assert_eq!(
                    format!("{:016x},{:016x},{:016x}", out.row_target.0[0].0, out.row_target.0[1].0, out.row_target.0[2].0),
                    kv["target"]
                );
            }
            "PSC_MASKS" => {
                let out = psc_output();
                let mc: Vec<E> = out.row_masks.iter().map(|m| m.coeff).collect();
                assert_eq!(hex(&mc), kv["PSC_MASKS"]);
            }
            "PSC_KEEPS" => {
                let out = psc_output();
                assert_eq!(out.row_maps.len().to_string(), kv["n"]);
                assert_eq!(out.row_maps[0].map.to_string(), kv["map"]);
                assert_eq!(
                    format!("{:016x},{:016x},{:016x}", out.row_maps[0].coeff.0[0].0, out.row_maps[0].coeff.0[1].0, out.row_maps[0].coeff.0[2].0),
                    kv["coeff"]
                );
                assert_eq!(out.ends.len().to_string(), kv["ends"]);
            }
            "PSC_END" => {
                let out = psc_output();
                assert_eq!(hex(&out.ends[0].point), kv["point"]);
                assert_eq!(
                    format!("{:016x},{:016x},{:016x}", out.ends[0].value.0[0].0, out.ends[0].value.0[1].0, out.ends[0].value.0[2].0),
                    kv["value"]
                );
                assert_eq!(out.ends[0].masks.len().to_string(), kv["masks"]);
            }
            _ => {}
        }
    }
    assert!(seen_ledger && seen_layout && seen_bat && seen_laid && seen_symbols && seen_batt);
}

fn laid_block() -> LaidBlock {
    LaidBlock {
        first_i: 0,
        first_c: 0,
        first_row: 0,
        first_place: 0,
        bits_i: 2,
        bits_c: 2,
        row_bits: 2,
        place_bits: 2,
        i_is_low: true,
    }
}

fn codes() -> Codes {
    Codes {
        base: vec![Code { log_n: 3, ell: 4, r: 2 }],
        mask: vec![Code { log_n: 2, ell: 4, r: 2 }],
    }
}

fn statement() -> (Statement, E, u32, u32) {
    let mut s = Statement::new(codes());
    let sa = OracleShape {
        name: "A".into(),
        code: 0,
        main_rows: 2,
        main_deg: 1,
        mask_rows: 2,
        mask_code: 0,
        answers: 1,
    };
    let sb = OracleShape {
        name: "B".into(),
        code: 0,
        main_rows: 1,
        main_deg: 3,
        mask_rows: 1,
        mask_code: 0,
        answers: 0,
    };
    let oa = s.sent(sa);
    let _ob = s.sent(sb);
    let mut sample = Row::plain("sample of A");
    sample.target = mk(900);
    s.sampled(
        &SendAccess,
        oa,
        vec![sample],
        Vec::new(),
        receipt_for_a_test(oa, 0, 4, 2, 1),
    );
    let g = s.new_group("G", 0, 0);
    s.join(g, oa, false);
    let mut r1 = Row::plain("r1");
    r1.add(oa, Part::Main, Tensor::eq(&[mk(1), mk(2), mk(3)], 3, E::one()));
    r1.add_unit(oa, Part::Main, 5, mk(11));
    r1.add_run(oa, Part::Main, 1, 2, vec![mk(12), mk(13)]);
    r1.target = mk(99);
    let mut r2 = Row::plain("r2");
    r2.add_unit(oa, Part::Mask, 0, mk(7));
    r2.target = mk(100);
    s.add_row(g, r1);
    s.add_row(g, r2);
    (s, mk(123), g, oa)
}

fn batt_rows() -> (Vec<TensorRow>, MaskLedger) {
    let f = [F(2), F(3), F(4)];
    let rows = vec![
        TensorRow {
            g: vec![Tensor::product(&f, 3, mk(7))],
            psi: vec![mk(1), mk(2)],
            masks: Vec::new(),
            target: mk(31),
        },
        TensorRow {
            g: vec![Tensor::product(&f, 3, mk(8))],
            psi: vec![mk(4), mk(5)],
            masks: Vec::new(),
            target: mk(32),
        },
    ];
    (rows, MaskLedger::new(receipt_for_a_test(5, 0, 20, 4, 2)))
}
fn psc_output() -> PscOutput {
    let mut pl = MaskLedger::new(receipt_for_a_test(6, 0, 50, 1, 0));
    let mut claim = SumClaim {
        vars: vec![Weight::plain(3), Weight::equality(mk(60), 3)],
        masks: vec![MaskTerm { slot: pl.take(), coeff: mk(62) }],
        target: mk(61),
    };
    let a0 = mk(63);
    let a1 = mk(64);
    let sm = Summand {
        shown: 1,
        kept: 1,
        degree: 1,
        at: Box::new(move |point: &[E], _y: &[E]| vec![a0 + point[0], a1]),
    };
    let vars = psc_vars(&claim, &sm);
    let fresh = pl.take_n(psc_masks(&claim, &sm));
    let challenges = [mk(70), mk(71), mk(72)];
    let ends = [mk(73)];
    let out = psc_rows(claim, &sm, &vars, fresh, mk(74), &challenges, mk(75), &ends);
    claim = SumClaim { vars: Vec::new(), masks: Vec::new(), target: E::zero() };
    let _ = claim;
    out
}
